files.file:
1 | package cmd
2 | 
3 | import (
4 | 	"fmt"
5 | 
6 | 	"github.com/spf13/cobra"
7 | 	"github.com/grzadr/gomper/internal/scanner"
8 | )
9 | 
10 | // NewProfilesCommand creates the profiles subcommand to list available embedded ignore profiles.
11 | func NewProfilesCommand() *cobra.Command {
12 | 	return &cobra.Command{
13 | 		Use:   "profiles",
14 | 		Short: "List available embedded gitignore profiles",
15 | 		RunE: func(cmd *cobra.Command, args []string) error {
16 | 			profiles, err := scanner.ListProfiles()
17 | 			if err != nil {
18 | 				return err
19 | 			}
20 | 
21 | 			out := cmd.OutOrStdout()
22 | 			_, _ = fmt.Fprintln(out, "Available ignore profiles:")
23 | 			for _, prof := range profiles {
24 | 				_, _ = fmt.Fprintf(out, "  - %s\n", prof)
25 | 			}
26 | 			return nil
27 | 		},
28 | 	}
29 | }
